        // Button outside Actions - no group parameter
        if (frm.doc.soil_sample_id) {
            frm.add_custom_button(__('View Sample'), function() {
                frappe.set_route('Form', 'Soil Sample Collection', frm.doc.soil_sample_id);
            });
