    discount_percent: function(frm) {
        calculate_payment_amounts(frm);
    },

    total_amount: function(frm) {
        calculate_payment_amounts(frm);
    },

    after_save: function(frm) {
        if (frm.doc.soil_sample_id) {
            frappe.show_alert({
                message: 'Payment saved! Redirecting to Sample...',
                indicator: 'green'
            }, 2);

            setTimeout(() => {
                frappe.set_route(
                    'Form',
                    'Soil Sample Collection',
                    frm.doc.soil_sample_id
                );
            }, 2000);
        }
    }
});

// ----------------------------------------------------
// Common Calculation Function
// ----------------------------------------------------
function calculate_payment_amounts(frm) {
    let total            = parseFloat(frm.doc.total_amount || 0);
    let discount_percent = parseFloat(frm.doc.discount_percent || 0);
    let discount_amount  = (total * discount_percent) / 100;
    let net_payable      = total - discount_amount;

    frm.set_value('discount_amount', discount_amount);
    frm.set_value('net_payable_amount', net_payable);
}

