            count
        );

        setTimeout(() => {
            calculate_total_parameter_count(frm);
        }, 300);

    });

}


// =====================================================
// 🔥 CONSULTANCY TOTAL
// =====================================================
function calculate_total_parameter_count(frm) {

    // ============================================
    // ONLY CONSULTANCY
    // ============================================
    if (
        (frm.doc.client_type || "")
        .toLowerCase()
        .trim() !== "consultancy"
    ) {

        return;
    }

    let total = 0;

    // ============================================
    // ADD TEST PARAMETER COUNTS
    // ============================================
    (frm.doc.tests || []).forEach(row => {

        total += cint(
            row.parameter_count || 0
        );

    });

    // ============================================
    // MULTIPLY BY NUMBER OF SAMPLES
    // ============================================
    let samples =
        cint(frm.doc.number_of_samples || 1);

    let final_total =
        total * samples;

    frm.set_value(
        'total_parameter_count',
        final_total
    );

}


// =====================================================
// 🔥 DEPARTMENT TOTAL
// =====================================================
async function calculate_department_total(frm) {

    // ============================================
    // ONLY DEPARTMENT
    // ============================================
    if (
        (frm.doc.client_type || "")
        .toLowerCase()
        .trim() !== "department"
    ) {

        return;
    }

    // ============================================
    // NAME OF TYPE REQUIRED
    // ============================================
    if (!frm.doc.name_of_type) {

        frm.set_value(
            'total_parameter_count',
            0
        );

        return;
    }

    try {

        // ============================================
        // GET DEPARTMENT PROGRAM
        // ============================================
        let dept_doc =
            await frappe.db.get_doc(
                'Department Programs Names',
                frm.doc.name_of_type
            );

        let total = 0;

        // ============================================
        // LOOP TEST LIST
        // ============================================
        for (
            let row of
            (dept_doc.test_list || [])
        ) {

            if (!row.test_item)
                continue;

            try {

                // ============================================
                // GET SOIL TEST PACKAGE
                // ============================================
                let pkg =
                    await frappe.db.get_doc(
                        'Soil Test Package',
                        row.test_item
                    );

                // ============================================
                // INCLUDED TESTS
                // ============================================
                if (
                    pkg.included_tests &&
                    pkg.included_tests.length
                ) {

                    for (
                        let child of
                        pkg.included_tests
                    ) {

                        if (
                            !child.linked_package
                        )
                            continue;

                        try {

                            // ============================================
                            // GET LINKED PACKAGE
                            // ============================================
                            let linked =
                                await frappe.db.get_doc(
                                    'Soil Test Package',
                                    child.linked_package
                                );

                            total += cint(
                                linked.parameter_count || 0
                            );

                        }

                        catch (e) {

                            console.log(e);

                        }

                    }

                }

                else {

                    total += cint(
                        pkg.parameter_count || 0
                    );

                }

            }

            catch (e) {

                console.log(e);

            }

        }

        // ============================================
        // MULTIPLY NUMBER OF SAMPLES
        // ============================================
        let samples =
            cint(frm.doc.number_of_samples || 1);

        let final_total =
            total * samples;

        // ============================================
        // FINAL TOTAL
        // ============================================
        frm.set_value(
            'total_parameter_count',
            final_total
        );

    }

    catch (e) {

        console.log(e);

    }

}

