function hide_form_sidebar(frm) {

    // Hide actual sidebar section
    if (frm.page.sidebar) {
        $(frm.page.sidebar).hide();
    }

    // Inject CSS to hide the toggle icon permanently
    if (!document.getElementById("hide-sidebar-style")) {

        let style = document.createElement("style");
        style.id = "hide-sidebar-style";
        style.innerHTML = `
            .page-title .sidebar-toggle-btn .sidebar-toggle-icon,
            .page-title .sidebar-toggle-btn .sidebar-toggle-placeholder {
                transition: all .5s ease-in-out;
                display: none !important;
            }
        `;
        document.head.appendChild(style);
    }
}

