// ── Populate variables for existing/new docs ──
function populate_variables(frm) {
    let master_promises = (frm.doc.results_table || []).map(row => {
        return frappe.db.get_doc('Soil Test Package', row.test_item).then(master => {
            return { row, master };
        });
    });

    Promise.all(master_promises).then(results => {
        results.forEach(({ row, master }) => {

            // Fix missing formula
            if (!row.formula && master.formula) {
                frappe.model.set_value(
                    row.doctype, row.name, 'formula', master.formula
                );
            }

            // Fix missing unit
            if (!row.unit && master.target_unit) {
                frappe.model.set_value(
                    row.doctype, row.name, 'unit', master.target_unit
                );
            }

            // Add variables if not already present
            (master.variable_table || []).forEach(v => {
                let already_exists = (frm.doc.variable_inputs || []).some(
                    vi => vi.variable_key === v.variable_key
                       && vi.parent_test_row === row.name
                );
                if (!already_exists) {
                    let var_row             = frm.add_child('variable_inputs');
                    var_row.variable_key    = v.variable_key;
                    var_row.description     = v.label;
                    var_row.parent_test_row = row.name;
                    var_row.test_item       = row.test_item;
                    var_row.value           = v.default_value || '';
                }
            });
        });

        frm.refresh_field('results_table');
        frm.refresh_field('variable_inputs');
    });
}

// ── Open popup for variable entry ──
function open_variable_popup(frm, test_row_name) {

    let test_row = (frm.doc.results_table || []).find(
        r => r.name === test_row_name
    );
    if (!test_row) return;

    let variables = (frm.doc.variable_inputs || []).filter(
        v => v.parent_test_row === test_row_name
    );

    // Variables empty → fetch on demand
    if (!variables.length) {
        frappe.db.get_doc('Soil Test Package', test_row.test_item).then(master => {

            if (!master.variable_table || !master.variable_table.length) {
                frappe.msgprint(
                    `No variables defined in Soil Test Package for ${test_row.test_item}`
                );
                return;
            }

            // Fix formula if missing
            if (!test_row.formula && master.formula) {
                frappe.model.set_value(
                    test_row.doctype, test_row.name, 'formula', master.formula
                );
            }

            // Add variables on the fly
            master.variable_table.forEach(v => {
                let var_row             = frm.add_child('variable_inputs');
                var_row.variable_key    = v.variable_key;
                var_row.description     = v.label;
                var_row.parent_test_row = test_row_name;
                var_row.test_item       = test_row.test_item;
                var_row.value           = v.default_value || '';
            });

            frm.refresh_field('variable_inputs');

            let fresh_variables = (frm.doc.variable_inputs || []).filter(
                v => v.parent_test_row === test_row_name
            );

            let updated_test_row = (frm.doc.results_table || []).find(
                r => r.name === test_row_name
            );

            show_popup(frm, updated_test_row, fresh_variables, test_row_name);
        });
        return;
    }

    show_popup(frm, test_row, variables, test_row_name);
}

// ── Show popup dialog ──
function show_popup(frm, test_row, variables, test_row_name) {

    let fields = variables.map(v => ({
        fieldtype : 'Float',
        fieldname : v.variable_key,
        label     : v.description || v.variable_key,
        default   : flt(v.value) || 0
    }));

    let dialog = new frappe.ui.Dialog({
        title               : `Enter Values — ${test_row.test_item}`,
        fields              : fields,
        primary_action_label: 'Calculate',
        primary_action      : function(values) {

            // Save values back to variable_inputs
            variables.forEach(v => {
                v.value = values[v.variable_key] || 0;
            });

            // Get latest test_row to ensure formula is present
            let latest_test_row = (frm.doc.results_table || []).find(
                r => r.name === test_row_name
            );

            let formula = latest_test_row && latest_test_row.formula
                ? latest_test_row.formula
                : test_row.formula;

            if (!formula) {
                frappe.msgprint('No formula defined for this test');
                return;
            }

            // Replace variable keys with values
            variables.forEach(v => {
                let val   = flt(v.value, 4) || 0;
                let regex = new RegExp("\\b" + v.variable_key + "\\b", "g");
                formula   = formula.replace(regex, val);
            });

            try {
                let result = eval(formula);

                frappe.model.set_value(
                    'Soil Test Result Entry',
                    test_row_name,
                    'final_result',
                    flt(result, 2)
                );

                frm.refresh_field('results_table');

                frappe.show_alert({
                    message  : `${test_row.test_item} = ${flt(result, 2)}`,
                    indicator: 'green'
                }, 3);

                dialog.hide();

            } catch(err) {
                frappe.msgprint(`Formula Error: ${err.message}`);
            }
        }
    });

    dialog.show();
}

