// =======================
// 🔹 GENERATE TABLE (FINAL)
// =======================
function generate_table(frm) {

    let data = {};

    (frm.doc.sample_data || []).forEach(row => {
        try {
            data[row.sample_id] = JSON.parse(row.values_json || "{}");
        } catch {
            data[row.sample_id] = {};
        }
    });

    // ==========================
    // 🔵 DEPARTMENT → ONLY sample_data
    // ==========================
    if (frm.doc.client_type === "Department") {

        let columns = new Set();

        Object.values(data).forEach(obj => {
            Object.keys(obj).forEach(k => columns.add(k));
        });

        let rows = Object.keys(data);

        if (rows.length === 0) {
            rows = [
                frm.doc.sample_id ||
                frm.doc.soil_sample_collection ||
                "SAMPLE"
            ];
        }

        build_table(frm, [...columns], rows);
        return;
    }

    // ==========================
    // 🟢 FARMER / CONSULTANCY → from tests
    // ==========================
    if (!frm.doc.tests || frm.doc.tests.length === 0) {

        // fallback if already saved data exists
        if (Object.keys(data).length > 0) {

            let columns = new Set();

            Object.values(data).forEach(obj => {
                Object.keys(obj).forEach(k => columns.add(k));
            });

            build_table(frm, [...columns], Object.keys(data));
            return;
        }

        frm.fields_dict.html.$wrapper.html("<p>No Tests Found</p>");
        return;
    }

    let test_list = [];

    (frm.doc.tests || []).forEach(d => {
        if (d.test_name) {
            test_list.push(String(d.test_name));
        }
    });

    frappe.call({
        method: "slis_app.api.Test_Input.get_columns",
        args: { test_list: test_list },
        callback: function(r) {

            let columns = Array.isArray(r.message) ? r.message : [];

            let sample = frm.doc.sample_id
                || frm.doc.soil_sample_collection
                || "SAMPLE";

            build_table(frm, columns, [sample]);
        }
    });
}


// =======================
// 🔹 BUILD TABLE
// =======================
function build_table(frm, final_tests, rows) {

    if (!Array.isArray(final_tests)) {
        final_tests = [final_tests];
    }

    final_tests = final_tests.map(t => String(t)).filter(t => t.length > 0);

    let data = {};

    (frm.doc.sample_data || []).forEach(row => {
        try {
            data[row.sample_id] = JSON.parse(row.values_json || "{}");
        } catch {
            data[row.sample_id] = {};
        }
    });

    let html = `
    <style>
    .table-container { width:100%; overflow-x:auto; }
    .custom-table { width:100%; min-width:max-content; }
    .custom-table th, .custom-table td { text-align:center; padding:6px; }
    .custom-table input { width:100%; min-width:80px; }
    </style>

    <div class="table-container">
    <table class="table table-bordered custom-table">
    <thead>
    <tr>
        <th style="min-width:220px;">Sample ID</th>`;

    final_tests.forEach(t => {
        html += `<th style="width:120px;">${t}</th>`;
    });

    html += `</tr></thead><tbody>`;

    rows.forEach(sample => {

        html += `<tr><td>${sample}</td>`;

        final_tests.forEach(t => {

            let value = data[sample]?.[t] || "";

            html += `
            <td>
                <input
                    value="${value}"
                    data-sample="${sample}"
                    data-test="${t}"
                    class="cell form-control"
                />
            </td>`;
        });

        html += `</tr>`;
    });

    html += `</tbody></table></div>`;

    frm.fields_dict.html.$wrapper.html(html);
}


// =======================
// 🔹 INPUT SAVE (COMMON)
// =======================
function bind_input_events(frm) {

    frm.fields_dict.html.$wrapper
        .off('input')
        .on('input', '.cell', function () {

            let sample = $(this).data('sample');
            let test   = $(this).data('test');
            let value  = $(this).val();

            update_json(frm, sample, test, value);
        });
}


// =======================
// 🔹 SAVE JSON
// =======================
function update_json(frm, sample, test, value) {

    let row = frm.doc.sample_data.find(d => d.sample_id === sample);

    if (!row) {
        row = frm.add_child('sample_data');
        row.sample_id   = sample;
        row.values_json = "{}";
    }

    let obj = {};

    try {
        obj = JSON.parse(row.values_json || "{}");
    } catch {
        obj = {};
    }

    obj[test] = value;

    row.values_json = JSON.stringify(obj);

    frm.refresh_field('sample_data');
    frm.dirty();
}

