// =====================================
// FINANCIAL YEAR
// =====================================

function get_financial_year(input_date) {

let d = new Date(input_date);

let year = d.getFullYear();
let month = d.getMonth() + 1;

let start =
    (month >= 4)
        ? year
        : year - 1;

let end = start + 1;

return `${String(start).slice(-2)}-${String(end).slice(-2)}`;
}

// =====================================
// GET LAST SAMPLE NUMBER
// =====================================

async function get_last_number(frm, base_prefix) {

let docs =
    await frappe.db.get_list(
        "Soil Sample Collection",
        {
            fields: ["name"],
            limit: 1000
        }
    );

let max = 0;

for (let d of docs) {

    let doc =
        await frappe.db.get_doc(
            "Soil Sample Collection",
            d.name
        );

    if (!doc.sample_data)
        continue;

    doc.sample_data.forEach(row => {

        if (!row.sample_id)
            return;

        if (
            row.sample_id.startsWith(
                base_prefix + "/"
            )
        ) {

            let num =
                parseInt(
                    row.sample_id
                        .split("/")
                        .pop()
                );

            if (
                !isNaN(num) &&
                num > max
            ) {

                max = num;

            }

        }

    });

}

return max;
}

// =====================================
// GET LAST LAB NUMBER
// Matches lab codes that start with
// lab_base + "/" — lab_base includes
// both prefix and FY so different FY
// or empty-prefix records are excluded
// =====================================

async function get_last_lab_number(lab_base) {

// guard: if lab_base starts with "/"
// prefix was empty — cannot match reliably

if (!lab_base || lab_base.startsWith("/")) {
    return 0;
}

let docs =
    await frappe.db.get_list(
        "Soil Sample Collection",
        {
            fields: ["name"],
            limit: 1000
        }
    );

let max = 0;

for (let d of docs) {

    let doc =
        await frappe.db.get_doc(
            "Soil Sample Collection",
            d.name
        );

    if (!doc.sample_data)
        continue;

    doc.sample_data.forEach(row => {

        if (!row.lab_code)
            return;

        if (
            row.lab_code.startsWith(
                lab_base + "/"
            )
        ) {

            let num =
                parseInt(
                    row.lab_code
                        .split("/")
                        .pop()
                );

            if (
                !isNaN(num) &&
                num > max
            ) {

                max = num;

            }

        }

    });

}

return max;
}

// =====================================
// GENERATE TABLE
// =====================================

async function render_table(
frm,
load_existing = false
) {

try {

    let is_farmer =
        (frm.doc.client_type || "")
        .toLowerCase()
        .trim() === "farmer";

    let is_consultancy =
        (frm.doc.client_type || "")
        .toLowerCase()
        .trim() === "consultancy";

    let count;

    if (is_farmer) {

        count = 1;

    } else {

        count = frm.doc.number_of_samples;

        if (!count) {

            return frappe.msgprint(
                "Enter number of samples"
            );

        }

    }

    // =====================================
    // DEPARTMENT VALIDATION
    // =====================================

    if (
        !is_consultancy &&
        !is_farmer &&
        !frm.doc.name_of_type
    ){

        return frappe.msgprint(
            "Select  Department Programs Names"
        );

    }

    let local_body =
        frm.doc.panchayath_name ||
        frm.doc.block_name ||
        "";

    if (
        !is_consultancy &&
        !is_farmer &&
        !local_body
    ) {

        return frappe.msgprint(
            "Select Panchayath or Block"
        );

    }

    let collection_date;

    // Farmer
    if (is_farmer) {

        collection_date =
            frm.doc.date_of_collection;

        if (!collection_date) {

            return frappe.msgprint(
                "Please select Date Of Collection"
            );
        }

    }
    // Others
    else {

        collection_date =
            frm.doc.collection_date;

        if (!collection_date) {

            return frappe.msgprint(
                "Please select Collection Date"
            );
        }
    }

    // =====================================
    // LAB PREFIX — MUST NOT BE EMPTY
    // =====================================

    let lab_prefix =
        (frm.doc.lab_code_prefix || "").trim();

    if (!lab_prefix) {

        return frappe.msgprint(
            "Please enter Lab Code Prefix"
        );

    }

    // =====================================
    // FINAL TESTS
    // =====================================

    let final_tests = [];
    if (
        is_farmer &&
        (!frm.doc.tests || frm.doc.tests.length === 0)
        ){

            frappe.msgprint(
                "Please add at least one test before generating the table."
            );

        return;
        }

    if (!is_consultancy && !is_farmer) {

        let type_doc =
            await frappe.db.get_doc(
                "Department Programs Names",
                frm.doc.name_of_type
            );

        for (
            let t of
            (type_doc.test_list || [])
        ) {

            try {

                let pkg =
                    await frappe.db.get_doc(
                        "Soil Test Package",
                        t.test_item
                    );

                if (
                    pkg.included_tests &&
                    pkg.included_tests.length > 1
                ) {

                    pkg.included_tests.forEach(
                        row => {

                            if (row.linked_package) {

                                final_tests.push(
                                    row.linked_package
                                );

                            }

                        }
                    );

                }

                else if (
                    pkg.included_tests &&
                    pkg.included_tests.length === 1
                ) {

                    final_tests.push(
                        pkg.included_tests[0]
                        .linked_package
                    );

                }

                else {

                    final_tests.push(
                        t.test_item
                    );

                }

            }

            catch {

                final_tests.push(
                    t.test_item
                );

            }

        }

    }

    else {

        for (
            let row of
            (frm.doc.tests || [])
        ) {

            if (!row.test_name)
                continue;

            try {

                let pkg =
                    await frappe.db.get_doc(
                        "Soil Test Package",
                        row.test_name
                    );

                if (
                    pkg.included_tests &&
                    pkg.included_tests.length > 1
                ) {

                    pkg.included_tests.forEach(
                        r => {

                            if (r.linked_package) {

                                final_tests.push(
                                    r.linked_package
                                );

                            }

                        }
                    );

                }

                else if (
                    pkg.included_tests &&
                    pkg.included_tests.length === 1
                ) {

                    final_tests.push(
                        pkg.included_tests[0]
                        .linked_package
                    );

                }

                else {

                    final_tests.push(
                        row.test_name
                    );

                }

            }

            catch {

                final_tests.push(
                    row.test_name
                );

            }

        }

    }

    // REMOVE DUPLICATES

    final_tests =
        [...new Set(final_tests)];

    // =====================================
    // PREFIX
    // =====================================

    let district =
        frm.doc.district_name || "";

    let fy =
        get_financial_year(
            collection_date
        );

    let base_prefix =
        `${district}/${frm.doc.name_of_type}/${fy}/${local_body}`;

    // lab_base = "PREFIX/FY"  e.g. "SES/26-27"
    // prefix validated above so never empty

    let lab_base =
        `${lab_prefix}/${fy}`;

    // =====================================
    // SAVED DATA
    // KEY IS LAST NUMBER
    // =====================================

    let saved_data = {};

    let highest_existing_number = 0;

    if (load_existing) {

        frm.doc.sample_data.forEach(row => {

            let last_no = "";

            if (is_farmer && row.sample_id) {

                last_no = String(
                    Object.keys(saved_data).length + 1
                );

            }

            else if (row.sample_id) {

                last_no =
                    row.sample_id
                    .split("/")
                    .pop();

            }

            if (!last_no) return;

            let num = parseInt(last_no);

            if (
                !isNaN(num) &&
                num > highest_existing_number
            ) {
                highest_existing_number = num;
            }

            saved_data[last_no] = {

                sample_id:
                    row.sample_id || "",

                lab_code:
                    row.lab_code || "",

                values:
                    JSON.parse(
                        row.values_json || "{}"
                    ),

                reference_name:
                    row.reference_name || ""

            };

        });

    }

    // =====================================
    // LAB CODE START NUMBER
    // =====================================

    let start_no =
        parseInt(
            frm.doc.lab_code_start
        );

    if (
        isNaN(start_no) ||
        start_no <= 0
    ) {

        start_no = 1;

    }

    let last_lab_number = 0;

    if (load_existing) {

        last_lab_number =
            highest_existing_number;

    } else {

        last_lab_number =
            await get_last_lab_number(
                lab_base
            );

    }

    let base_number;

    if (load_existing) {

        base_number = 1;

    } else {

        if (last_lab_number === 0) {
            base_number = start_no;
        } else {
            base_number = last_lab_number + 1;
        }

    }

    // =====================================
    // LAST NUMBER
    // =====================================

    let last_number = 0;

    if (
        !load_existing &&
        !is_consultancy
    ) {

        last_number =
            await get_last_number(
                frm,
                base_prefix
            );

    } else if (load_existing) {

        last_number = highest_existing_number;

    }

    // =====================================
    // HTML
    // =====================================

    let html = `
    <style>

    .table-container {
        width: 100%;
        overflow-x: auto;
        cursor: grab;
    }

    .custom-table {
        width: max-content;
        min-width: 100%;
        border-collapse: collapse;
    }

    .custom-table th,
    .custom-table td {
        text-align: center;
        padding: 6px;
        white-space: nowrap;
        border: 1px solid #ddd;
    }

    .custom-table th {
        background: #f5f5f5;
        font-weight: 600;
    }

    .custom-table input {
        width: 100%;
        min-width: 80px;
    }

    </style>

    <div class="table-container">

    <table class="table table-bordered custom-table">

    <thead>

    <tr>`;

    if (!is_consultancy && !is_farmer) {

        html += `
        <th style="min-width:220px;">
        Sample ID
        </th>`;

    }

    if (is_farmer) {

        html += `
        <th style="min-width:220px;">
        Sample ID
        </th>`;

    }

    html += `
    <th style="min-width:180px;">
    Lab Code
    </th>`;

    if (is_consultancy) {

        html += `
        <th style="min-width:180px;">
        Reference Name
        </th>`;

    }

    final_tests.forEach(t => {

        html += `
        <th style="width:120px;">
        ${t}
        </th>`;

    });

    html += `
    </tr>
    </thead>
    <tbody>`;

    let existing_keys =
        Object.keys(saved_data);

    // =====================================
    // ROWS
    // =====================================

    for (
        let i = 1;
        i <= count;
        i++
    ) {

        let sample_id = "";
        let lab_code = "";
        let reference_name = "";
        let existing_values = {};

        let existing_key =
            existing_keys[i - 1];

        let existing_row =
            existing_key
                ? saved_data[existing_key]
                : null;

        if (existing_row) {

            sample_id =
                existing_row.sample_id || "";

            let existing_lab_number =
                existing_row.lab_code
                    ? existing_row.lab_code
                        .split("/")
                        .pop()
                    : "";

            if (existing_lab_number) {

                lab_code =
                    `${lab_base}/${existing_lab_number}`;

            } else {

                lab_code =
                    existing_row.lab_code || "";

            }

            reference_name =
                existing_row.reference_name || "";

            existing_values =
                existing_row.values || {};

        } else {

            let extra =
                i - existing_keys.length;

            if (!is_consultancy && !is_farmer) {

                let new_sample_number =
                    last_number + extra;

                sample_id =
                    `${base_prefix}/${new_sample_number}`;

            }

            if (is_farmer) {

                // await frm.save();

                // await frm.reload_doc();

                // sample_id = frm.doc.name;
                // Farmer sample id = document name
                sample_id = frm.doc.name || "";

                // If document is not saved yet
                if (
                    !sample_id ||
                    sample_id.startsWith("new-")
                ) {

                frappe.msgprint(
                    "Please save the document once before generating the table."
                    );

                return;
                } 


            }

            let new_lab_number =
                last_lab_number + extra;

            lab_code =
                `${lab_base}/${new_lab_number}`;

        }

        html += `<tr>`;

        if (!is_consultancy) {

            html += `
            <td>${sample_id}</td>`;

        }

        html += `
        <td>${lab_code}</td>`;

        if (is_consultancy) {

            html += `
            <td>

            <input
                type="text"

                value="${reference_name}"

                data-lab="${lab_code}"

                class="reference-name-input form-control">

            </td>`;

        }

        final_tests.forEach(t => {

            let value =
                existing_values[t] || "";

            html += `
            <td>

            <input
                type="text"

                value="${value}"

                data-sample="${sample_id}"

                data-lab="${lab_code}"

                data-test="${t}"

                class="test-input form-control">

            </td>`;

        });

        html += `</tr>`;

    }

    html += `
    </tbody>
    </table>
    </div>`;

    frm.fields_dict.html
        .$wrapper.html(html);
        console.log("TABLE GENERATED");
        console.log(html);

    // =====================================
    // DRAG SCROLL
    // =====================================

    let container =
        frm.fields_dict.html
        .$wrapper.find(
            '.table-container'
        );

    let isDown = false;

    let startX;

    let scrollLeft;

    container.off(
        'mousedown mouseleave mouseup mousemove'
    );

    container.on(
        'mousedown',
        function(e) {

            isDown = true;

            startX =
                e.pageX -
                container.offset().left;

            scrollLeft =
                container.scrollLeft();

        }
    );

    container.on(
        'mouseleave mouseup',
        function() {

            isDown = false;

        }
    );

    container.on(
        'mousemove',
        function(e) {

            if (!isDown)
                return;

            e.preventDefault();

            let x =
                e.pageX -
                container.offset().left;

            let walk =
                (x - startX) * 2;

            container.scrollLeft(
                scrollLeft - walk
            );

        }
    );

}

catch (error) {

    console.error(error);

    frappe.msgprint(
        "Error generating table"
    );

}
}

