// SAVE TABLE DATA
// =====================================

async function save_table_data(frm) {

try {

    frm.clear_table("sample_data");

    let rows = frm.fields_dict.html.$wrapper
        .find("tbody tr");

    rows.each(function() {

        let row = $(this);

        let is_consultancy =
            (frm.doc.client_type || "")
            .toLowerCase()
            .trim() == "consultancy";

        let is_farmer =
            (frm.doc.client_type || "")
            .toLowerCase()
            .trim() === "farmer";

        let sample_id = "";

        if (!is_consultancy) {

            sample_id =
                row.find("td")
                .eq(0)
                .text()
                .trim();

        }

        let lab_index =
            is_consultancy ? 0 : 1;

        let lab_code =
            row.find("td")
            .eq(lab_index)
            .text()
            .trim();

        let reference_name = "";

        if (is_consultancy) {

            reference_name =
                row.find(
                    ".reference-name-input"
                ).val() || "";

        }

        let values_json = {};

        row.find(".test-input").each(
            function() {

                let input =
                    $(this);

                let test =
                    input.data("test");

                let value =
                    input.val();

                values_json[test] =
                    value;

            }
        );

        let child =
            frm.add_child(
                "sample_data"
            );

        child.sample_id =
            sample_id;

        child.lab_code =
            lab_code;

        child.reference_name =
            reference_name;

        child.values_json =
            JSON.stringify(
                values_json
            );

    });

    frm.refresh_field(
        "sample_data"
    );

    await frm.save();

    frappe.show_alert({

        message:
            "Table Data Saved",

        indicator:
            "green"

    });

}

catch (e) {

    console.error(e);

    frappe.msgprint(
        "Error Saving Table Data"
    );

}
}

