frappe.listview_settings['Clients'] = {
    refresh: function(listview) {
        let attempts = 0;
        const interval = setInterval(() => {
            const rows = $('.list-row-container .list-row');
            if (rows.length > 0 || attempts > 10) {
                clearInterval(interval);

                rows.each(function() {
                    const $row = $(this);
                    const docname = $row.find('.list-row-checkbox').attr('data-name');

                    // Prevent duplicate buttons
                    if (docname && !$row.find('.btn-samples-custom').length) {
                        const btn = $(`
                            <div class="level-item list-row-activity hidden-xs" style="margin-left: 10px;">
                                <button class="btn btn-xs btn-default btn-samples-custom" 
                                        style="
                                            border: 2px solid #d1d8dd; 
                                            background-color: #1c1c1c;
                                            color: #d1d8dd;
                                            padding: 4px 8px;
                                            font-size: 12px;
                                            border-radius: 4px;
                                            transition: all 0.2s;
                                            margin-right: 24px;
                                        ">
                                    Show Samples
                                </button>
                            </div>
                        `);

                        btn.on('click', function(e) {
                            e.preventDefault();
                            e.stopPropagation();
                            frappe.set_route("List", "Soil Sample Collection", { "client": docname });
                        });

                        // Append to the 'level-right' container to push it to the far right
                        $row.find('.level-right').prepend(btn);
                    }
                });
            }
            attempts++;
        }, 500);
    }
};

