frappe.listview_settings['Soil Sample Collection'] = {
    refresh: function(listview) {
        // 1. Automatically discover the correct Child DocType name from parent metadata fields
        if (!listview.detected_child_doctype) {
            let parent_meta = frappe.get_meta(listview.doctype);
            if (parent_meta && parent_meta.fields) {
                let table_fields = parent_meta.fields.filter(f => f.fieldtype === 'Table');
                for (let table of table_fields) {
                    let child_meta = frappe.get_meta(table.options);
                    if (child_meta && child_meta.fields && child_meta.fields.some(cf => cf.fieldname === 'test_name')) {
                        listview.detected_child_doctype = table.options;
                        break;
                    }
                }
            }
        }

        // Initialize persistent filter tracking states safely
        if (listview.current_client_type === undefined) listview.current_client_type = null;
        if (listview.current_child_test === undefined) listview.current_child_test = null;
        if (listview.in_test_menu === undefined) listview.in_test_menu = false;

        listview.test_package_mappings = {
            'Micro Nutrients': ['Micro nutrient Analysis(സൂക്ഷ്മ പോഷക വിശകലനം)'],
            'Secondary Nutrients': ['Secondary nutrient Analysis(ദ്വിതീയ പോഷക വിശകലനം)'],
            'Routine Analysis': ['Routine Analysis(പതിവ് വിശകലനം)']
        };

        // Render the correct toolbar view based on navigation depth state
        if (listview.in_test_menu) {
            render_farmer_test_buttons(listview);
        } else {
            render_client_type_buttons(listview);
        }
    }
};

// Hook safely into the List View global class prototype layer to compile payload on-demand
if (frappe.views.ListView) {
    const original_get_args = frappe.views.ListView.prototype.get_args;
    frappe.views.ListView.prototype.get_args = function() {
        let args = original_get_args.call(this);

        if (this.doctype === 'Soil Sample Collection') {
            if (!args.filters) args.filters = [];

            // Inject parent client type restriction if active (Farmer, Consultancy, Department)
            if (this.current_client_type) {
                args.filters.push([this.doctype, 'client_type', '=', this.current_client_type]);
            }

            // Inject child table test item restriction if active
            if (this.current_child_test && this.detected_child_doctype) {
                let test_rule = this.current_child_test;
                args.filters.push([this.detected_child_doctype, 'test_name', test_rule.op, test_rule.val]);
            }
        }
        return args;
    };
}

function render_client_type_buttons(listview) {
    listview.page.clear_inner_toolbar();
    listview.in_test_menu = false;

    const client_types = ['Farmer', 'Consultancy', 'Department'];

    client_types.forEach(type => {
        listview.page.add_inner_button(__(type), function() {
            listview.filter_area.clear();
            listview.current_client_type = type;
            listview.current_child_test = null; // Clear old child filters

            if (type === 'Farmer') {
                listview.in_test_menu = true;
                render_farmer_test_buttons(listview);
                listview.refresh();
            } else {
                listview.refresh();
            }
        }, __('Filter by Client'));
    });
}

function render_farmer_test_buttons(listview) {
    listview.page.clear_inner_toolbar();

    listview.page.add_inner_button(__('⬅ Back'), function() {
        // Reset both filter rules when hitting back to start fresh
        listview.current_client_type = null;
        listview.current_child_test = null;
        listview.filter_area.clear();
        render_client_type_buttons(listview);
        listview.refresh();
    }, __('Filter by Test'));

    const test_categories = ['Micro Nutrients', 'Secondary Nutrients', 'Routine Analysis', 'Others'];

    test_categories.forEach(category => {
        listview.page.add_inner_button(__(category), function() {
            listview.filter_area.clear();

            if (category === 'Others') {
                let main_packages = [
                    'Micro nutrient Analysis(സൂക്ഷ്മ പോഷക വിശകലനം)',
                    'Secondary nutrient Analysis(ദ്വിതീയ പോഷക വിശകലനം)',
                    'Routine Analysis(പതിവ് വിശകലനം)'
                ];
                listview.current_child_test = { op: 'not in', val: main_packages };
            } else {
                let target_package = listview.test_package_mappings[category] || [];
                if (target_package.length > 0) {
                    listview.current_child_test = { op: 'in', val: target_package };
                }
            }

            listview.refresh();
        }, __('Filter by Test'));
    });
}

frappe.listview_settings["Soil Sample Collection"] = {
    onload: function(listview) {
        listview.page.add_action_item(
            "Move to Multiple Sample Entry",
            function() {
                const selected = listview.get_checked_items();

                if (!selected.length) {
                    frappe.msgprint("Please select at least one sample.");
                    return;
                }

                const sample_ids = selected.map(s => s.name);
                const param = encodeURIComponent(JSON.stringify(sample_ids));
                window.location.href = `/app/multiple-sample-entry?results=${param}`;
            }
        );
    }
};

frappe.listview_settings["Soil Sample Collection"] = {
    add_fields: ["is_master_sample", "client_type"],

    refresh(listview) {
        setTimeout(() => {

            listview.data.forEach(doc => {

                if (
                    doc.is_master_sample &&
                    ["Department", "Consultancy"].includes(doc.client_type)
                ) {

                    let $row = listview.$result.find(
                        `[data-name="${doc.name}"]`
                    );

                    // Disable the checkbox
                    $row.find('input[type="checkbox"]')
                        .prop("disabled", true)
                        .prop("checked", false);

                    // Make it visually disabled
                    $row.find('.list-row-checkbox')
                        .css({
                            "opacity": "0.4",
                            "pointer-events": "none"
                        });
                }
            });

        }, 500);
    }
};

frappe.listview_settings['Soil Sample Collection'] = {

    onload(listview) {

        listview.page.add_action_item(
            __('Verify Physical Sample'),
            function () {

                let selected = listview.get_checked_items();

                if (!selected.length) {
                    frappe.msgprint(__('Please select one or more samples'));
                    return;
                }

                frappe.confirm(
                    __('Mark selected samples as physically verified?'),
                    function () {

                        let promises = [];

                        selected.forEach(row => {

                            promises.push(
                                frappe.db.set_value(
                                    'Soil Sample Collection',
                                    row.name,
                                    'verified_physical_sample',
                                    1
                                )
                            );

                        });

                        Promise.all(promises)
                            .then(() => {

                                frappe.show_alert({
                                    message: __('Physical samples verified'),
                                    indicator: 'green'
                                });

                                listview.refresh();

                            });

                    }
                );

            }
        );

    }
};

frappe.listview_settings['Soil Sample Collection'] = {
    onload: function(listview) {
        $(listview.page.btn_toolbar).empty();

        // Label is "Filter Client Type", Class is "btn-primary"
        listview.page.add_inner_button(__('Filter Client Type'), () => {
            ssc_start_filter_flow(listview);
        }, 'Filter based on test');

        listview.page.add_inner_button(__('Reset Filters'), () => {
            listview.filter_area.clear();
        });
    }
};

function ssc_start_filter_flow(listview) {
    let d1 = new frappe.ui.Dialog({
        title: 'Select Client Type',
        fields: [{ 
            label: 'Client Type', 
            fieldname: 'client_type', 
            fieldtype: 'Select', 
            options: 'Farmer\nDepartment\nConsultancy',
            reqd: 1 
        }],
        primary_action: (values) => {
            d1.hide();
            show_test_dialog(listview, values.client_type);
        }
    });
    d1.show();
}

function show_test_dialog(listview, client_type) {
    let d2 = new frappe.ui.Dialog({
        title: 'Select Test Name',
        fields: [{ 
            label: 'Test Package', 
            fieldname: 'test_name', 
            fieldtype: 'Link', 
            options: 'Soil Test Package',
            reqd: 1 
        }],
        primary_action: async (values) => {
            d2.hide();
            await apply_final_filter(listview, client_type, values.test_name);
        }
    });
    d2.show();
}

async function apply_final_filter(listview, client_type, test_name) {
    frappe.show_alert(__('Filtering...'));
    const docs = await frappe.db.get_list('Soil Sample Collection', {
        filters: { client_type: client_type },
        fields: ['name']
    });

    const matched_names = [];
    for (let d of docs) {
        const doc = await frappe.db.get_doc('Soil Sample Collection', d.name);
        const has_test = (doc.sample_data || []).some(row => {
            if (!row.values_json) return false;
            try {
                const json_data = JSON.parse(row.values_json);
                return Object.keys(json_data).some(k => k.includes(test_name));
            } catch (e) { return false; }
        });
        if (has_test) matched_names.push(d.name);
    }
    listview.filter_area.clear();
    listview.filter_area.add([['Soil Sample Collection', 'client_type', '=', client_type]]);
    listview.filter_area.add([['Soil Sample Collection', 'name', 'in', matched_names]]);
}

frappe.ui.form.on("Department Program Year Wise", {
    program: function(frm) {
        if (!frm.doc.program) return;

        frappe.db.get_doc("Department Programs Names", frm.doc.program)
            .then(doc => {
                // Clear existing tests
                frm.clear_table("test_list");

                // Copy tests from master
                (doc.test_list || []).forEach(row => {
                    let child = frm.add_child("test_list");
                    child.test_item = row.test_item;
                });

                frm.refresh_field("test_list");
            });
    }
});

frappe.ui.form.on("Department Program Year Wise", {
    refresh(frm) {
        if (frm.is_new()) return;

        frm.add_custom_button(__("Show Samples"), function() {

            if (!frm.doc.program || !frm.doc.financial_year) {
                frappe.msgprint(__("Please select Program and Financial Year"));
                return;
            }

            frappe.db.get_doc("Fiscal Year", frm.doc.financial_year)
                .then(fy => {

                    frappe.set_route(
                        "List",
                        "Soil Sample Collection",
                        {
                            client_type: "Department",
                            name_of_type: frm.doc.program,
                            collection_date: [
                                "between",
                                [
                                    fy.year_start_date,
                                    fy.year_end_date
                                ]
                            ]
                        }
                    );

                });
        });
    }
});

frappe.ui.form.on("Clients", {
    refresh: async function(frm) {

        let r = await frappe.db.get_value(
            "Employee",
            { user_id: frappe.session.user },
            "employment_type"
        );

        if (r.message && r.message.employment_type === "Lab") {

            frm.set_df_property(
                "client_type",
                "options",
                ["Farmer", "Consultancy"]
            );

            if (frm.doc.client_type === "Department") {
                frm.set_value("client_type", "");
            }
        }
    }
});
